const today = new Date(); today.setHours(0, 0, 0, 0);
const ymd = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const MONTHS = { jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11 };
const text = d => !d ? '' : (typeof d === 'string' ? d : JSON.stringify(d));
function parseDue(f) {
  if (f.duedate) return new Date(f.duedate + 'T00:00:00');
  const t = text(f.description);
  const iso = t.match(/deadline[^0-9]*(\d{4}-\d{2}-\d{2})/i) || t.match(/(\d{4}-\d{2}-\d{2})/);
  if (iso) return new Date(iso[1] + 'T00:00:00');
  const md = t.match(/deadline[^a-z0-9]*([a-z]{3})[a-z]*\.?\s+(\d{1,2})(?:,?\s*(\d{4}))?/i);
  if (md && MONTHS[md[1].toLowerCase()] !== undefined) return new Date(Number(md[3] || today.getFullYear()), MONTHS[md[1].toLowerCase()], Number(md[2]));
  return null;   // "No deadline" or vague → never reported as overdue
}
function assigneeOf(f) {
  if (f.assignee && f.assignee.displayName) return f.assignee.displayName;
  const m = (f.summary || '').match(/\(([^()]+)\)\s*$/);
  return m ? m[1].trim() : 'Unassigned';
}
const overdue = [];
for (const it of $input.all()) {
  const i = it.json, f = i.fields || {};
  const due = parseDue(f);
  if (!due || isNaN(due) || due >= today) continue;
  overdue.push({ key: i.key, summary: f.summary, assignee: assigneeOf(f), due: ymd(due), days: Math.round((today - due) / 864e5) });
}
if (!overdue.length) return [{ json: { count: 0, text: '' } }];
const byPerson = {};
overdue.forEach(o => (byPerson[o.assignee] = byPerson[o.assignee] || []).push(o));
let msg = `⏰ *Weekly overdue actions* (${overdue.length})\n`;
for (const [p, items] of Object.entries(byPerson)) {
  msg += `\n*${p}*\n` + items.map(o => `• ${o.summary} — due ${o.due} (${o.days}d overdue) · ${o.key}`).join('\n') + '\n';
}
return [{ json: { count: overdue.length, text: msg } }];
